
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m08_hx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m08_hx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.550618597230133e+00, -1.509990667685774e+00, -1.458693678460943e+00, -1.398149182587552e+00, -1.332509103779713e+00, -1.263871579681086e+00, -1.186078874051339e+00, -1.149024138385358e+00, -1.209743758882593e+00, -9.238118781510593e-01, -5.755432186292612e-01, -3.310356775851616e-01, -2.749519272530288e-01, -2.352013102816339e-01, -2.128996519220974e-01, -1.333828663391567e-01, -4.843998589656937e-02, 7.274974070958043e-03, 4.512609609034803e-03, 5.273346000023978e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


